html:
{% set copies_per_page = 3 %}

{# ===== THEME ===== #}
{% set BRAND = "#0F62FE" %}
{% set INK = "#111111" %}
{% set SUBTLE = "#666666" %}
{% set BORDER = "#222222" %}

{% macro short_item_name(it) -%}{{ (it.item_name or it.item_code)|replace(" ","-") }}{%- endmacro %}

{# ----- ADDRESS / CONTACT ----- #}
{% set addr_name = doc.shipping_address_name or doc.customer_address %}
{% if addr_name %}
  {% set address = frappe.get_doc("Address", addr_name) %}
  {% set address_line1 = address.address_line1 or "" %}
  {% set address_line2 = address.address_line2 or "" %}
  {% set city = address.city or "" %}
  {% set state = address.state or "" %}
  {% set country = address.country or "" %}
  {% set pincode = address.pincode or "" %}
  {% set phone = address.phone or "" %}
{% else %}
  {% set address_line1 = "" %}{% set address_line2 = "" %}
  {% set city = "" %}{% set state = "" %}{% set country = "" %}{% set pincode = "" %}{% set phone = "" %}
{% endif %}

{% set contact_person = doc.contact_display or doc.contact_person or "" %}
{% set contact_phone = doc.custom_contact_number or doc.contact_phone or doc.contact_mobile %}
{% if not contact_phone and doc.customer %}
  {% set contact_phone = frappe.db.get_value("Customer", doc.customer, "mobile_no") %}
{% endif %}

{# ----- ITEMS LINE (safe with namespace) ----- #}
{% set ns = namespace(parts=[]) %}
{% for it in doc.items %}
  {% set qty = (it.qty or 0)|float %}
  {% set one = short_item_name(it) ~ " (" ~ (qty|round(0)|int) ~ ")" %}
  {% set ns.parts = ns.parts + [one] %}
{% endfor %}
{% set books_line = ns.parts|join(", ") %}
{% if books_line|length > 650 %}
  {% set books_line = books_line[:650] ~ "…" %}
{% endif %}


{% set company_name = frappe.db.get_value("Company", doc.company, "company_name") or doc.company %}
{% set logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
{% set comp_phone = frappe.db.get_value("Company", doc.company, "phone_no") %}

<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Delivery Labels</title>
<style>
  /* ===== PAGE (A4) ===== */
  @page { size: A4; margin: 8mm; }
  html,body{margin:0;padding:0;}
  *{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  body{font-family:Arial,Helvetica,sans-serif;color:{{ INK }};}

  /* Flexible row height so long content doesn't get clipped */
  .labels{
    display:grid;
    grid-auto-rows: minmax(88mm, auto);   /* min 88mm, can grow if needed */
    gap:6mm;
  }

  /* ===== SINGLE LABEL ===== */
  .label{
    position:relative;
    border:1px solid {{ BORDER }}; border-radius:6px; background:#fff;
    display:grid; grid-template-columns:1fr 128px;  /* left | right */
    break-inside:avoid; page-break-inside:avoid;
    overflow:visible;   /* allow growth */
  }

  /* accent rail */
  .label::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:{{ BRAND }};}

  /* watermark */
  .wm{
    position:absolute; left:6px; right:6px; top:50%;
    transform:translateY(-50%) rotate(-22deg);
    text-align:center; font-size:60px; font-weight:900; letter-spacing:6px;
    color: rgba(15,98,254,0.08); pointer-events:none; user-select:none; z-index:3;
  }

  .left,.right{position:relative; z-index:4;}
  .left{padding:8px 10px 8px 12px; display:flex; flex-direction:column; gap:6px;}
  .right{
    border-left:1px solid {{ BORDER }};
    background: linear-gradient(180deg, rgba(247,249,254,0.92), rgba(238,242,251,0.92));
    display:flex; flex-direction:column; align-items:center; justify-content:center; gap:6px;
    padding:10px 8px;
  }

  .topbar{
    display:flex;align-items:center;justify-content:space-between;gap:10px;
    border:1px solid {{ BORDER }}; border-radius:6px;
    background: rgba(255,255,255,0.92);
    padding:6px 8px;
  }
  .brand{display:flex;align-items:center;gap:8px;min-width:0;}
  .brand .logo{width:26px;height:26px;object-fit:contain;border-radius:4px;border:1px solid {{ BORDER }};background:#fff;}
  .brand .company{font-weight:800;font-size:12.5px;letter-spacing:.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap;justify-content:flex-end;}
  .pill{font-size:10px;line-height:1;padding:5px 8px;border:1px solid {{ BORDER }};border-radius:999px;background:#fff;color:{{ SUBTLE }};}
  .pill b{color:{{ INK }};}

  .row{display:flex;gap:2px;align-items:flex-end;}
  .lbl{width:138px;font-weight:700;font-size:11px;color:{{ INK }};}
  .val{flex:1;min-height:1px;padding:2px 2px 2px;border-bottom:1px dashed {{ SUBTLE }};background:transparent;}

  .addr,.notes{
    border:1px solid {{ BORDER }}; border-radius:6px;
    background:#fff; opacity:.92;
    padding:8px 10px; font-size:11px; line-height:1.35;
    word-break:break-word; overflow-wrap:anywhere;
  }

  /* Optional: cap the notes box height to always keep 3 labels per page.
     If you want this behavior, uncomment the two lines below. */
  /* .notes{ max-height:36mm; overflow:hidden; } */

  .footer{
    margin-top:auto;border-top:1px solid {{ BORDER }};
    display:flex;align-items:center;justify-content:space-between;gap:8px;padding-top:4px;
    background: transparent;
  }
  .pair{display:flex;align-items:center;gap:6px;}
  .valbox{min-width:48px;padding:3px 6px 1px;text-align:center;border:1px solid {{ BORDER }};border-radius:4px;font-weight:700;background:#fff;}

  .tag{font-size:10px;letter-spacing:.8px;text-transform:uppercase;color:{{ SUBTLE }};}
  .ofy{font-size:11px;}
  .qr{width:66px;height:66px;margin-top:2px;}


  .notes {
  border: 1px solid {{ BORDER }};
  border-radius: 6px;
  background: #fff;
  opacity: .92;
  padding: 8px 10px;
  font-size: 11px;
  line-height: 1.35;
  word-break: break-word;
  overflow-wrap: anywhere;
  white-space: normal;     /* ✅ important for line breaks */
}

</style>
</head>
<body>

<div class="labels">
  {% for _i in range(copies_per_page) %}
  <div class="label">
    <div class="wm">ILM FOUNDATION</div>

    <div class="left">
      <div class="topbar">
        <div class="brand">
          {% if logo %}<img class="logo" src="{{ logo }}">{% endif %}
          <div class="company">{{ company_name }}</div>
        </div>
        <div class="meta">
          <span class="pill"><b>DN#:</b> {{ doc.name }}</span>
          <span class="pill"><b>Date:</b> {{ frappe.utils.formatdate(doc.posting_date or doc.creation) }}</span>
          {% if doc.set_warehouse %}<span class="pill"><b>WH:</b> {{ doc.set_warehouse }}</span>{% endif %}
        </div>
      </div>

      <div class="row">
        <div class="lbl">Organization</div>
        <div class="val">{{ doc.customer or "-" }}</div>
      </div>

      <div class="row">
        <div class="lbl">Contact Detail</div>
        <div class="val">
         {{ doc.custom_first_name or "" }} {{ contact_phone if contact_phone else "" }}
        </div>
      </div>

      <div class="addr">
  {% set addr_parts = [] %}
  {% if address_line1 %}{% set addr_parts = addr_parts + [address_line1] %}{% endif %}
  {% if address_line2 %}{% set addr_parts = addr_parts + [address_line2] %}{% endif %}
  {% if city %}{% set addr_parts = addr_parts + [city] %}{% endif %}
  {% if state %}{% set addr_parts = addr_parts + [state] %}{% endif %}
  {% if country %}{% set addr_parts = addr_parts + [country] %}{% endif %}
  {% if pincode %}{% set addr_parts = addr_parts + [pincode] %}{% endif %}
  {{ addr_parts|join(", ") }}
  {% if phone %}<b> | Ph:</b> {{ phone }}{% endif %}
</div>

      <div class="notes">
  <div style="white-space: normal;">
    <strong>Books / Items:</strong>
    {{ books_line or "-" }}
  </div>
  <div style="margin-top:6px;">
    <b>From:</b> {{ company_name }}
    {% if comp_phone %}
      <span class="muted">&nbsp;•&nbsp;Ph:</span> {{ comp_phone }}
    {% endif %}
  </div>
</div>

      <div class="footer">
        <div class="pair"><b>Total Cartons</b> <span class="valbox">{{ doc.custom_total_cartons or "-" }}</span></div>
        <div class="pair"><b>Prepared By</b> <span class="valbox" style="width:64px; text-align:center;">{{ doc.owner.split('@')[0] if doc.owner else "-" }}</span></div>
      </div>
    </div>

    <div class="right">
      <div class="tag">Carton</div>
      <div class="ofy">{% if doc.custom_total_cartons not in ["", None, "-"] %}of {{ doc.custom_total_cartons }}{% else %}&nbsp;{% endif %}</div>
      <img class="qr"
        src="https://api.qrserver.com/v1/create-qr-code/?size=132x132&data={{ 'https://tif.edu.pk/' | urlencode }}"
        alt="QR">
    </div>
  </div>
  {% endfor %}
</div>

</body>
</html>
